INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(37318031, 'R - Righteous Justice', 'R－公平正义', 'R－ライトジャスティス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：选自己场上的「元素英雄」卡数量的场上的魔法·陷阱卡破坏。'),
(73783043, 'R-Genex Accelerator', '真次代机・加速器', 'レアル・ジェネクス・アクセラレーター', 'Effect Monster', 'Machine', 'WIND', 4, 1500, 1900, '①：这张卡在怪兽区域存在的状态，「次世代」怪兽从自己卡组加入手卡时，把那之内的1只给对方观看才能发动。给人观看的怪兽特殊召唤。'),
(65149697, 'R-Genex Crusher', '真次代机・粉碎机', 'レアル・ジェネクス・クラッシャー', 'Effect Monster', 'Machine', 'EARTH', 2, 800, 800, '①：这张卡召唤时才能发动。从卡组把1只4星「真次世代」怪兽加入手卡。'),
(1533292, 'R-Genex Magma', '真次代机・锅炉', 'レアル・ジェネクス・マグナ', 'Effect Monster', 'Pyro', 'FIRE', 3, 1000, 200, '①：这张卡召唤时才能发动。从卡组把1只2星「真次世代」怪兽加入手卡。'),
(10178757, 'R-Genex Oracle', '真次代机・预言机', 'レアル・ジェネクス・オラクル', 'Tuner Monster', 'Spellcaster', 'DARK', 1, 300, 300, '把这张卡作为同调素材的场合，不是「次世代」怪兽的同调召唤不能使用。 ①：这张卡用「次世代」怪兽的效果从自己卡组加入手卡的场合才能发动。这张卡特殊召唤。'),
(32744558, 'R-Genex Overseer', '真次代机・司令塔', 'レアル・ジェネクス・コーディネイター', 'Tuner Monster', 'Spellcaster', 'DARK', 2, 200, 100, '①：这张卡召唤·特殊召唤时才能发动。从手卡把1只3星以下的「次世代」怪兽特殊召唤。'),
(6256844, 'R-Genex Turbo', '真次代机・涡轮', 'レアル・ジェネクス・ターボ', 'Effect Monster', 'Machine', 'WIND', 4, 1500, 1300, '①：这张卡召唤时才能发动。从卡组把1只1星「次世代」怪兽加入手卡。'),
(61052897, 'R-Genex Turing', '真次代机・图灵机', 'レアル・ジェネクス・チューリング', 'Tuner Monster', 'Spellcaster', 'DARK', 2, 600, 600, '这个卡名的①的效果1回合只能使用1次。 ①：对方主要阶段，自己场上有「次世代」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。那之后，可以进行1只「次世代」同调怪兽的同调召唤。 ②：把场上的这张卡作为「次世代」同调怪兽的同调素材的场合，可以把这张卡的等级当作1星或者3星使用。'),
(46572756, 'R-Genex Ultimum', '真次代机・极金', 'レアル・ジェネクス・ウルティマム', 'Effect Monster', 'Machine', 'EARTH', 4, 1800, 1400, '①：场上的表侧表示的这张卡被破坏送去墓地时，以自己墓地2只「次世代」怪兽为对象才能发动。那些怪兽回到卡组。'),
(34568783, 'R-Genex Undine', '真次代机・水精灵', 'レアル・ジェネクス・ウンディーネ', 'Effect Monster', 'Aqua', 'WATER', 4, 1700, 1100, '①：1回合1次，从自己墓地把1只「次世代」怪兽除外才能发动。这张卡的属性也当作和那只怪兽相同属性使用。把调整除外发动的场合，可以再把这张卡直到回合结束时当作调整使用。 ②：自己场上有「次世代」同调怪兽存在的场合，以包含这张卡的自己墓地2只「次世代」怪兽为对象才能发动。那些怪兽加入手卡。这个回合，被送去自己墓地的卡不去墓地而除外。'),
(78710386, 'R.B. Funk Dock', '奏悦机组 疯克对接站', NULL, 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '作为这张卡发动时的效果处理：从卡组把「奏悦机组 疯克对接站」以外的1张「奏悦机组」卡加入手卡。 每次对方场上的怪兽被战斗·效果破坏，自己回复500基本分。 自己场上的表侧表示「奏悦机组」怪兽因卡的效果从场上离开的场合（伤害步骤除外）：可以从卡组把1只「奏悦机组」怪兽特殊召唤。「奏悦机组 疯克对接站」的这个效果1回合只能使用1次。 「奏悦机组 疯克对接站」在1回合只能发动1张。 '),
(33438265, 'R.B. Ga10 Cutter', '奏悦机组 筑工切割机', NULL, 'Effect Monster', 'Machine', 'EARTH', 4, 700, 700, '自己场上的表侧表示怪兽不存在的场合或者只有「奏悦机组」怪兽的场合，这张卡可以从手卡特殊召唤。自己对「奏悦机组 筑工切割机」的这个方法的特殊召唤1回合只能有1次。 这张卡在「奏悦机组」连接怪兽所连接区存在，对方把魔法·陷阱卡的效果发动时（诱发即时效果）：可以支付700基本分；这张卡破坏，那个效果无效并破坏。「奏悦机组 筑工切割机」的这个效果1回合只能使用1次。 '),
(6043161, 'R.B. Ga10 Driller', '奏悦机组 筑工钻机', NULL, 'Effect Monster', 'Machine', 'EARTH', 3, 500, 500, '自己场上的表侧表示怪兽不存在的场合或者只有「奏悦机组」怪兽的场合，这张卡可以从手卡特殊召唤。自己对「奏悦机组 筑工钻机」的这个方法的特殊召唤1回合只能有1次。 主要阶段，这张卡在「奏悦机组」连接怪兽所连接区存在的场合（诱发即时效果）：可以支付500基本分，以对方场上1只怪兽为对象；那只怪兽和这张卡破坏。「奏悦机组 筑工钻机」的这个效果1回合只能使用1次。'),
(44573911, 'R.B. Ga10 Pile Bunker', '奏悦机组 筑工冲击锥', NULL, 'Effect Monster', 'Machine', 'EARTH', 8, 1500, 1500, '自己场上的表侧表示怪兽不存在的场合或者只有「奏悦机组」怪兽的场合，这张卡可以从手卡特殊召唤。「奏悦机组 筑工冲击锥」的这个方法的特殊召唤1回合只能有1次。 有这张卡在所连接区的「奏悦机组 狂放蓝调号」和对方怪兽进行战斗的攻击宣言时：可以支付1500基本分；对方场上的卡和这张卡全部破坏。「奏悦机组 筑工冲击锥」的这个效果1回合只能使用1次。'),
(17188206, 'R.B. Lambda Blade', '奏悦机组 λ羔羊刃', NULL, 'Effect Monster', 'Machine', 'DARK', 7, 1400, 1400, '这张卡召唤·特殊召唤的场合：可以从卡组把「奏悦机组 λ羔羊刃」以外的1张「奏悦机组」卡送去墓地。 对方主要阶段，这张卡在「奏悦机组」连接怪兽所连接区存在的场合（诱发即时效果）：可以支付1400基本分，以对方场上1只怪兽为对象；这张卡破坏，得到作为对象的怪兽的控制权。这个效果得到控制权的怪兽在结束阶段破坏。 「奏悦机组 λ羔羊刃」的每个效果1回合各能使用1次。'),
(81794107, 'R.B. Lambda Cannon', '奏悦机组 λ羔羊炮', NULL, 'Effect Monster', 'Machine', 'DARK', 6, 1200, 1200, '这张卡召唤·特殊召唤的场合：可以以「奏悦机组 λ羔羊炮」以外的自己墓地1只「奏悦机组」怪兽为对象；那只怪兽加入手卡。 这张卡在「奏悦机组」连接怪兽所连接区存在的场合：可以支付1200基本分；这张卡破坏，把对方的手卡确认，那之后可以把其中1只怪兽在对方场上效果无效特殊召唤。 「奏悦机组 λ羔羊炮」的每个效果1回合各能使用1次。'),
(43450363, 'R.B. Last Stand', '奏悦机组 背水一战', NULL, 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从自己的卡组·额外卡组·墓地把同名卡不在自己场上存在的1只「奏悦机组」怪兽特殊召唤。这张卡的发动后，直到回合结束时自己不是攻击力在1500以下的机械族怪兽不能从额外卡组特殊召唤。 自己场上的「奏悦机组」怪兽为对象的卡的效果由对方发动时：可以从自己墓地把这张卡除外；那个效果无效。 「奏悦机组 背水一战」的效果1回合只能有1次使用其中任意1个。'),
(79859067, 'R.B. Next Phase', '奏悦机组 阶段转换', NULL, 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上有「奏悦机组」怪兽存在，对方把怪兽的效果发动时：自己场上1只怪兽破坏，那个发动无效并破坏，那之后，自己回复2000基本分。 「奏悦机组 阶段转换」在1回合只能发动1张。'),
(16066654, 'R.B. Operation Test', '奏悦机组 运转试验', NULL, 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的发动时：可以以自己墓地1只3星以上的「奏悦机组」怪兽为对象；那只怪兽特殊召唤。 可以以自己场上的「奏悦机组」怪兽任意数量为对象；自己回复那个原本攻击力合计数值的基本分，作为对象的怪兽回到手卡·额外卡组，那之后，可以从手卡把1只「奏悦机组」怪兽特殊召唤。「奏悦机组 运转试验」的这个效果1回合只能使用1次。 「奏悦机组 运转试验」在1回合只能发动1张。'),
(80071619, 'R.B. Shepherd''s Crook', '奏悦机组 牧羊人权杖', NULL, 'Link Monster', 'Machine', 'DARK', NULL, 1500, NULL, '包含「奏悦机组」怪兽的怪兽2只以上 这张卡的攻击力上升这张卡以外的自己怪兽的数量×500。 「奏悦机组 牧羊人权杖」的以下效果1回合各能使用1次。 自己主要阶段：可以从自己的卡组·墓地把1张「奏悦机组」陷阱卡在自己场上盖放。 对方主要阶段（诱发即时效果）：可以以自己墓地的3只3星以上的「奏悦机组」怪兽为对象；那之内的2只用喜欢的顺序回到卡组最下面，剩下的守备表示特殊召唤。'),
(5109321, 'R.B. Stage Landing', '奏悦机组 舞台登场', NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己的卡组·额外卡组把同名卡不在自己场上存在的1只「奏悦机组」怪兽特殊召唤。 自己场上的「奏悦机组」怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。 这张卡发动的回合，自己不是原本攻击力在1500以下的机械族怪兽不能从额外卡组特殊召唤。 '),
(32216688, 'R.B. The Brute Blues', '奏悦机组 狂放蓝调号', NULL, 'Link Monster', 'Machine', 'WIND', NULL, 1500, NULL, '机械族怪兽2只以上 这张卡所连接区有「奏悦机组」怪兽存在的场合，这张卡得到以下效果。 ●这张卡的攻击力上升这张卡所连接区的「奏悦机组」怪兽的原本攻击力合计数值。 ●这张卡在同1次的战斗阶段中可以作2次攻击。 ●这张卡不会被战斗·效果破坏。 自己主要阶段：可以从卡组把1张「奏悦机组」卡加入手卡。「奏悦机组 狂放蓝调号」的这个效果1回合只能使用1次。'),
(6821579, 'R.B. VALCan Booster', '奏悦机组 火神推进器', NULL, 'Link Monster', 'Machine', 'FIRE', NULL, 500, NULL, '机械族怪兽2只 这张卡连接召唤的场合：可以从卡组把1张「奏悦机组」魔法卡加入手卡。 这张卡在额外怪兽区域存在的场合：可以从自己的手卡·墓地把1只「奏悦机组」怪兽守备表示特殊召唤。那之后，可以把这张卡的位置向其他的自己主要怪兽区域移动。直到回合结束时，自己不是攻击力在1500以下的机械族怪兽不能从额外卡组特殊召唤。 「奏悦机组 火神推进器」的每个效果1回合各能使用1次。'),
(79436874, 'R.B. VALCan Rocket', '奏悦机组 火神火箭', NULL, 'Effect Monster', 'Machine', 'FIRE', 5, 1000, 1000, '自己场上的表侧表示怪兽不存在的场合或者只有「奏悦机组」怪兽的场合，这张卡可以从手卡特殊召唤。自己对「奏悦机组 火神火箭」的这个方法的特殊召唤1回合只能有1次。 这张卡在「奏悦机组」连接怪兽所连接区存在的场合：可以支付1000基本分，以对方场上最多2张卡为对象；那些卡破坏。这张卡破坏。给与对方这个效果破坏的卡的数量×500的伤害。「奏悦机组 火神火箭」的这个效果1回合只能使用1次。 '),
(74875003, 'Ra''s Disciple', '拉之使徒', 'ラーの使徒', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1100, 600, '①：这张卡召唤·反转召唤·特殊召唤成功时才能发动。从手卡·卡组把最多2只「太阳神的使徒」特殊召唤。 ②：只要这张卡在怪兽区域存在，自己不用「太阳神的使徒」的效果不能把怪兽特殊召唤，这张卡不能为「奥西里斯之天空龙」「欧贝利斯克之巨神兵」「太阳神之翼神龙」的上级召唤以外而解放。'),
(30163008, 'Ra''ten, the Heavenly General', '罗天神将', '羅天神将', 'Link Monster', 'Warrior', 'EARTH', NULL, 2200, NULL, '相同种族的怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：自己·对方的准备阶段，以这张卡所连接区1只表侧表示怪兽为对象才能发动。种族和那只怪兽相同的1只4星以下的怪兽从手卡往作为这张卡所连接区的自己场上特殊召唤。 ②：自己·对方的战斗阶段开始时，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(94905343, 'Rabid Horseman', '牛头人马兽', 'ミノケンタウロス', 'Fusion Monster', 'Beast-Warrior', 'EARTH', 6, 2000, 1700, '「牛头人」＋「人马兽」'),
(95788410, 'Rabidragon', '兔龙', 'ラビードラゴン', 'Normal Monster', 'Dragon', 'LIGHT', 8, 2950, 2900, '雪原上栖息的龙类突然变异种。巨大的耳朵可分辨距离数千米远的声音，结合惊人跳跃力让盯上的猎物无处可逃。'),
(28674153, 'Radian Token', '多次元坏兽掠地昂', '多次元壊獣ラディアン', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(28674152, 'Radian, the Multidimensional Kaiju', '多次元坏兽掠地昂', '多次元壊獣ラディアン', 'Effect Monster', 'Fiend', 'DARK', 7, 2800, 2500, '①：这张卡可以把对方场上1只怪兽解放，从手卡往对方场上攻击表示特殊召唤。 ②：对方场上有「坏兽」怪兽存在的场合，这张卡可以从手卡攻击表示特殊召唤。 ③：「坏兽」怪兽在自己场上只能有1只表侧表示存在。 ④：1回合1次，把自己·对方场上2个坏兽指示物取除才能发动。在自己场上把1只「拉迪安衍生物」（恶魔族·暗·7星·攻2800/守0）特殊召唤。这衍生物不能作为同调素材。'),
(86310763, 'Radiance of the Voiceless Voice', '肃声威光', '粛声なる威光', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的主要阶段，可以从以下效果选择1个发动。 ●从自己的手卡·墓地让1只战士族·龙族而光属性的仪式怪兽或者1张仪式魔法卡回到卡组，从卡组选1只「肃声」怪兽加入手卡或特殊召唤。 ●以最多有自己场上的战士族·龙族而光属性的仪式怪兽数量的对方场上的卡为对象才能发动。那些卡和这张卡破坏。'),
(84177693, 'Radiant Jeral', '神圣天使', 'ホーリー・ジェラル', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1000, 2000, '场上有「天空的圣域」存在的场合，这张卡被战斗破坏以外的方法送去墓地时，自己回复1000基本分。'),
(21481146, 'Radiant Mirror Force', '闪光防护罩 -光明之力-', '閃光のバリア －シャイニング・フォース－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上攻击表示怪兽有3只以上存在的场合，对方的攻击宣言时才能发动。对方场上的攻击表示怪兽全部破坏。'),
(12624008, 'Radiant Spirit', '光明之灵', 'シャインスピリッツ', 'Effect Monster', 'Reptile', 'LIGHT', 7, 2000, 1500, '这张卡被战斗破坏送去墓地时，场上表侧表示存在的光属性怪兽以外的怪兽全部破坏。'),
(25940932, 'Radiant Typhoon Ascendance', '绚岚之轩昂', '絢嵐たる軒昂', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●从自己墓地把1只6星以下的「绚岚」怪兽特殊召唤。 ●从自己的卡组·墓地把1张「旋风」加入手卡。 ②：这张卡被「旋风」的效果破坏的场合才能发动。这张卡在自己的魔法与陷阱区域盖放。'),
(67115133, 'Radiant Typhoon Chant', '绚岚之献咏', '絢嵐たる献詠', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●从卡组把1只4星以下的「绚岚」怪兽加入手卡。 ●从自己的卡组·墓地把1张「旋风」加入手卡。 ②：这张卡被「旋风」的效果破坏的场合才能发动。这张卡在自己的魔法与陷阱区域盖放。'),
(54143349, 'Radiant Typhoon Eldam', '绚岚之达象', '絢嵐たるエルダム', 'Effect Monster', 'Beast', 'WIND', 3, 1300, 800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己墓地有「旋风」存在的场合或者对方场上没有魔法·陷阱卡存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把「绚岚之达维」以外的1只「绚岚」怪兽或1张「旋风」加入手卡。'),
(85315450, 'Radiant Typhoon Fonix, the Great Flame', '绚岚豪火 凤尼克斯', '絢嵐豪火フォニクス', 'Effect Monster', 'Pyro', 'WIND', 9, 3000, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：速攻魔法卡发动的场合才能发动。这张卡从手卡特殊召唤。 ②：速攻魔法卡发动的场合，以对方场上最多2张卡为对象才能发动。那些卡回到卡组。 ③：这张卡在墓地存在的状态，「旋风」发动的场合才能发动。这张卡特殊召唤。'),
(16922142, 'Radiant Typhoon Krosea', '绚岚之鹤罗莎', '絢嵐たるクローゼア', 'Effect Monster', 'Winged Beast', 'WIND', 6, 2200, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：速攻魔法卡发动的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。「绚岚之罗莎」以外的「绚岚」卡和「旋风」各最多1张从自己的卡组·墓地加入手卡。这个效果的发动后，直到回合结束时自己不是风属性怪兽不能特殊召唤。 ③：对方场上没有魔法·陷阱卡存在的场合，场上的这张卡不会被战斗·效果破坏。'),
(53813120, 'Radiant Typhoon Mandate', '绚岚之权能', '絢嵐たる権能', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，以包含「绚岚」卡的自己墓地3张速攻魔法卡为对象才能发动。以下适用。 ●那些卡回到卡组。那之后，自己抽1张。 ●这个回合中，自己场上的风属性怪兽的攻击力·守备力上升300。 ②：「旋风」发动时，以对方场上1张表侧表示卡为对象才能发动（同一连锁上最多1次）。那张卡的效果无效。 ③：这张卡被「旋风」的效果破坏的场合才能发动。这张卡在自己场上盖放。'),
(94103142, 'Radiant Typhoon Manifestation', '绚岚之显现', '絢嵐たる顕現', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●从卡组把1只「绚岚」怪兽送去墓地。 ●从自己的卡组·墓地把1张「旋风」加入手卡。 ②：这张卡被「旋风」的效果破坏的场合才能发动。这张卡在自己的魔法与陷阱区域盖放。'),
(27755794, 'Radiant Typhoon Meghala', '绚岚之米葛拉', '絢嵐たるメガラ', 'Effect Monster', 'Fairy', 'WIND', 3, 500, 1500, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己墓地有「旋风」存在的场合或者对方场上没有魔法·陷阱卡存在的场合，这张卡可以从手卡特殊召唤。 ②：「绚岚」速攻魔法卡或「旋风」发动的场合才能发动。同名怪兽不在自己场上存在的1只「绚岚」怪兽从卡组特殊召唤。这个效果的发动后，直到回合结束时自己不是风属性怪兽不能特殊召唤。'),
(80538047, 'Radiant Typhoon Swen', '绚岚之狲', '絢嵐たるスエン', 'Effect Monster', 'Beast-Warrior', 'WIND', 3, 1600, 400, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己墓地有「旋风」存在的场合或者对方场上没有魔法·陷阱卡存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「绚岚」魔法·陷阱卡或「旋风」加入手卡。'),
(39341885, 'Radiant Typhoon Varuroon, the Marine Eidolon', '绚岚之海灵 伐楼仑', '絢嵐たる海霊ヴァルルーン', 'Link Monster', 'Aqua', 'WIND', NULL, NULL, NULL, '「绚岚」怪兽2只 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从自己的卡组·墓地把1张「旋风」加入手卡。 ②：以包含自己场上的「绚岚」怪兽的场上2只表侧表示怪兽为对象才能发动。那些怪兽当作永续魔法卡使用在原本持有者的魔法与陷阱区域表侧表示放置。 ③：速攻魔法卡发动的场合才能发动。从自己的卡组·墓地把1张「绚岚」永续陷阱卡在自己场上表侧表示放置。'),
(53927851, 'Radiant Typhoon Varuroon, the Vibrant Vortex', '绚岚涡丽 伐楼仑', '絢嵐渦麗ヴァルルーン', 'Effect Monster', 'Aqua', 'WIND', 9, NULL, 3000, '这个卡名的①②③的效果1回合各能使用1次。 ①：速攻魔法卡发动的场合才能发动。这张卡从手卡特殊召唤。 ②：自己墓地有「旋风」存在，对方把怪兽的效果发动时才能发动。那个效果无效。自己墓地有「旋风」2张以上存在的场合，可以再把那只怪兽破坏。 ③：这张卡在墓地存在的状态，「旋风」发动的场合才能发动。这张卡特殊召唤。'),
(20508881, 'Radiant Typhoon Vision', '绚岚之见神', '絢嵐たる見神', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●自己抽2张。那之后，手卡有「绚岚」卡或速攻魔法卡存在的场合，选那之内的1张丢弃。不存在的场合，自己手卡全部丢弃。 ●从自己的卡组·墓地把1张「旋风」加入手卡。 ②：这张卡被「旋风」的效果破坏的场合才能发动。这张卡在自己的魔法与陷阱区域盖放。'),
(70856343, 'Radiant Vouirescence', '契珖之荧光亚龙', '契珖のヴルーレセンス', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1600, 800, '①：对方场上有怪兽存在，这张卡召唤成功时，丢弃1张手卡才能发动。从卡组把「契珖之荧光亚龙」任意数量送去墓地。 ②：1回合1次，这张卡在墓地存在的场合才能发动。墓地的这张卡直到回合结束时变成暗属性。'),
(6483224, 'Radius, the Half-Moon Dragon', '半月龙 半径龙', '半月竜ラディウス', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1400, 1200, '对方场上有超量怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤的这张卡的等级变成8星。'),
(38916526, 'Rafale, Champion Fur Hire', '空牙团的英雄 拉法尔', '空牙団の英雄 ラファール', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2800, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。把「空牙团的英雄 拉法尔」以外的自己场上的「空牙团」怪兽种类数量的卡从自己卡组上面翻开，从那之中选1张加入手卡，剩余回到卡组。 ②：对方把怪兽的效果发动时，从手卡丢弃1张「空牙团」卡才能发动。那个发动无效。'),
(31440542, 'Rafflesia Seduction', '幻惑之大花草', '幻惑のラフレシア', 'Flip Effect Monster', 'Plant', 'EARTH', 2, 300, 900, '反转：直到回合结束前，得到对方场上的1只表侧表示的怪兽的控制权。'),
(82685480, 'Rage of Kairyu-Shin', '海龙神之怒', '海竜神の怒り', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：场上有「海」存在的场合，以最多有自己场上的原本等级是5星以上的水属性怪兽数量的对方场上的怪兽为对象才能发动。那些怪兽破坏。直到下个回合的结束时，那些怪兽存在过的区域不能使用。'),
(73778008, 'Rage of the Deep Sea', '深海之怒', '深海の怒り', 'Effect Monster', 'Fish', 'WATER', 5, NULL, NULL, '这张卡的攻击力·守备力上升自己墓地存在的鱼族·海龙族·水族怪兽数量×500的数值。'),
(33955120, 'Rage Rose Witch', '黑蔷薇与荆棘之魔女', '黒薔薇と荊棘の魔女', 'Synchro Monster', 'Plant', 'DARK', 6, 1600, 2400, '调整＋调整以外的怪兽1只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从卡组·额外卡组各把最多1只植物族怪兽送去墓地。这个效果的发动后，直到回合结束时自己不是同调怪兽不能从额外卡组特殊召唤。 ②：自己场上的植物族怪兽不会被效果破坏。 ③：这张卡在墓地存在的状态，场上的卡被效果破坏的场合才能发动。这张卡特殊召唤。'),
(29432790, 'Rage with Eyes of Blue', '青之眼的激临', '青き眼の激臨', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不是「青眼白龙」不能召唤·特殊召唤。 ①：包含这张卡的自己的手卡·场上·墓地的卡全部里侧表示除外，从卡组把最多3只「青眼白龙」特殊召唤。'),
(23639291, 'Raging Cloudian', '攻击性云魔物', 'アグレッシブ・クラウディアン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的名字带有「云魔物」的怪兽被自身的效果破坏送去墓地时才能发动。从自己墓地把那1只怪兽攻击表示特殊召唤，并给那只怪兽放置1个雾指示物。这个效果特殊召唤的怪兽不会被卡的效果变成守备表示。'),
(50957346, 'Raging Earth', '狂怒大地', 'レイジアース', 'Effect Monster', 'Reptile', 'EARTH', 7, 2000, 1500, '这张卡被战斗破坏送去墓地时，场上表侧表示存在的地属性怪兽以外的怪兽全部破坏。'),
(56524813, 'Raging Eria', '逆卷之艾莉娅', '逆巻くエリア', 'Effect Monster', 'Spellcaster', 'WATER', 4, 800, 1500, '可以把自己场上除这张卡以外的1只水属性怪兽做祭品，从手卡特殊召唤1只水属性怪兽。这个效果1回合只能使用1次。这个效果特殊召唤的怪兽，在「逆卷之艾莉娅」从自己场上离开的场合破坏。'),
(90810762, 'Raging Flame Sprite', '逆卷的炎之精灵', '逆巻く炎の精霊', 'Effect Monster', 'Pyro', 'FIRE', 3, 100, 200, '这张卡可以直接攻击对方玩家。这张卡直接攻击给与对方基本分战斗伤害时，这张卡的攻击力上升1000。'),
(95507060, 'Raging Mad Plants', '狂植物的泛滥', '狂植物の氾濫', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的植物族怪兽的攻击力直到这个回合的结束阶段时上升自己墓地存在的植物族怪兽数量×300的数值。这个回合的结束阶段时，自己场上表侧表示存在的植物族怪兽全部破坏。'),
(8836329, 'Raging Storm Dragon - Beaufort IX', '飓风龙-蒲福九风龙', '颶風龍－ビュフォート・ノウェム', 'Ritual Effect Monster', 'Dragon', 'WIND', 9, 2800, 2800, '「褒誉之息吹」降临。这个卡名的①②的效果1回合各能使用1次。 ①：对方怪兽的直接攻击宣言时把这张卡从手卡丢弃才能发动。那次攻击无效，那只怪兽的效果无效化。 ②：以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽和这张卡回到持有者手卡。这个效果在对方回合也能发动。'),
(52543404, 'Ragnaraika Armored Lizard', '蕾祸之铠石龙', '蕾禍ノ鎧石竜', 'Effect Monster', 'Reptile', 'DARK', 4, NULL, 2300, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以把自己墓地1只昆虫族·植物族·爬虫类族怪兽除外，从手卡特殊召唤。 ②：从手卡丢弃1只昆虫族·植物族·爬虫类族怪兽，以昆虫族·植物族·爬虫类族怪兽以外的对方场上1只表侧表示怪兽为对象才能发动。那只怪兽回到手卡。'),
(4841383, 'Ragnaraika Bloom', '蕾祸缭乱狂绽', '蕾禍繚乱狂咲', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：场上的昆虫族·植物族·爬虫类族怪兽的攻击力·守备力上升300，那以外的场上的怪兽的攻击力·守备力下降300。 ②：可以从以下效果选择1个发动。 ●从卡组把1只「蕾祸」怪兽加入手卡。那之后，选自己1张手卡丢弃。 ●自己的手卡·墓地·除外状态的1只「蕾祸」怪兽守备表示特殊召唤。'),
(6908161, 'Ragnaraika Chain Coils', '蕾祸之锁蛇巳', '蕾禍ノ鎖蛇巳', 'Link Monster', 'Reptile', 'FIRE', NULL, 2900, NULL, '包含昆虫族·植物族·爬虫类族怪兽的怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：对方把怪兽的效果发动的场合才能发动。这个回合，双方不能把手卡的怪兽的效果发动。 ②：这张卡在墓地存在的场合，以自己场上1只昆虫族·植物族·爬虫类族怪兽为对象才能发动。那只怪兽回到卡组最下面，这张卡特殊召唤。这个回合，自己不是昆虫族·植物族·爬虫类族怪兽不能特殊召唤。'),
(89824842, 'Ragnaraika Hunting Dance', '蕾祸大轮首狩舞', '蕾禍大輪首狩舞', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以最多有自己场上的昆虫族·植物族·爬虫类族连接怪兽的种族种类数量的对方场上的卡为对象才能发动。那些卡破坏。 ②：这个回合没有送去墓地的这张卡在墓地存在的状态，自己场上的表侧表示的昆虫族·植物族·爬虫类族怪兽被战斗·效果破坏的场合，把这张卡除外，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(70514456, 'Ragnaraika Mantis Monk', '蕾祸之御拜神主', '蕾禍ノ御拝神主', 'Link Monster', 'Insect', 'WIND', NULL, 2300, NULL, '包含昆虫族·植物族·爬虫类族怪兽的怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把2只昆虫族·植物族·爬虫类族怪兽除外才能发动。从卡组把1张「蕾祸」陷阱卡加入手卡。 ②：这张卡在墓地存在的场合，以自己场上1只昆虫族·植物族·爬虫类族怪兽为对象才能发动。那只怪兽回到卡组最下面，这张卡特殊召唤。这个回合，自己不是昆虫族·植物族·爬虫类族怪兽不能特殊召唤。'),
(26548709, 'Ragnaraika Samurai Beetle', '蕾祸之矢筈天牛', '蕾禍ノ矢筈天牛', 'Effect Monster', 'Insect', 'LIGHT', 3, 1500, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以让自己的除外状态的1只昆虫族·植物族·爬虫类族怪兽回到卡组最下面，从手卡特殊召唤。 ②：这张卡作为「蕾祸」连接怪兽的连接素材送去墓地的场合，以除「蕾祸之矢筈天牛」外的自己墓地1只4星以下的昆虫族·植物族·爬虫类族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(75352507, 'Ragnaraika Selene Snapper', '蕾祸之玄神凭月', '蕾禍ノ玄神憑月', 'Link Monster', 'Reptile', 'WATER', NULL, 2600, NULL, '昆虫族·植物族·爬虫类族怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把最多2只怪兽除外，以那个数量的对方场上的魔法·陷阱卡为对象才能发动。那些卡破坏。 ②：这张卡在墓地存在的场合，以自己场上1只昆虫族·植物族·爬虫类族怪兽为对象才能发动。那只怪兽回到卡组最下面，这张卡特殊召唤。这个回合，自己不是昆虫族·植物族·爬虫类族怪兽不能特殊召唤。'),
(43129357, 'Ragnaraika Skeletal Soldier', '蕾祸之武者骷髅', '蕾禍ノ武者髑髏', 'Link Monster', 'Plant', 'FIRE', NULL, 1600, NULL, '包含昆虫族·植物族·爬虫类族怪兽的怪兽2只 这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不是昆虫族·植物族·爬虫类族怪兽不能特殊召唤。 ①：以自己墓地1只「蕾祸」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ②：这张卡在墓地存在的场合，以自己场上1只昆虫族·植物族·爬虫类族怪兽为对象才能发动。那只怪兽回到卡组最下面，这张卡特殊召唤。'),
(42307760, 'Ragnaraika Stag Sovereign', '蕾祸之大王鬼牙', '蕾禍ノ大王鬼牙', 'Link Monster', 'Insect', 'EARTH', NULL, 3300, NULL, '昆虫族·植物族·爬虫类族怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：从对方的卡组·额外卡组有怪兽特殊召唤的场合才能发动。场上2只怪兽破坏。 ②：这张卡在墓地存在的场合，以自己场上1只昆虫族·植物族·爬虫类族怪兽为对象才能发动。那只怪兽回到卡组最下面，这张卡特殊召唤。这个回合，自己不是昆虫族·植物族·爬虫类族怪兽不能特殊召唤。'),
(99153051, 'Ragnaraika the Evil Seed', '蕾祸之毬首', '蕾禍ノ毬首', 'Effect Monster', 'Plant', 'EARTH', 1, NULL, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以把手卡1只昆虫族·植物族·爬虫类族怪兽送去墓地，从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。「蕾祸之毬首」以外的自己的卡组·除外状态的最多2张「蕾祸」卡加入手卡（同名卡最多1张）。那之后，选自己1张手卡除外。这个回合，自己不是昆虫族·植物族·爬虫类族怪兽不能特殊召唤。'),
(97262307, 'Ragnaraika Wicked Butterfly', '蕾祸之姬邪眼', '蕾禍ノ姫邪眼', 'Effect Monster', 'Insect', 'EARTH', 4, 1800, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。从手卡把1只昆虫族·植物族·爬虫类族怪兽特殊召唤。 ②：这张卡从手卡·墓地除外的场合才能发动。这个回合的结束阶段，自己抽出自己场上的昆虫族·植物族·爬虫类族怪兽的种族种类的数量。'),
(77573354, 'Ragnaraika Wisteria of Woe', '蕾祸之曝藤', '蕾禍ノ曝藤', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡发动后变成通常怪兽（植物族·暗·4星·攻1600/守0）在怪兽区域特殊召唤（也当作陷阱卡使用）。自己场上有「蕾祸」连接怪兽存在的场合，可以再从对方墓地把最多2张卡除外。 ②：自己·对方的结束阶段，这张卡在墓地存在的场合才能发动。自己的墓地·除外状态的2只昆虫族·植物族·爬虫类族怪兽回到卡组，这张卡在自己场上盖放。'),
(32548318, 'Rahu Dracotail', '罗睺星宿', '羅睺星辰', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的手卡·卡组·场上的怪兽作为融合素材，把1只「星辰」融合怪兽融合召唤。这张卡的发动后，直到回合结束时自己不是融合怪兽不能从额外卡组特殊召唤。'),
(31173519, 'Rai Rider', '雷骑手', 'ライライダー', 'Effect Monster', 'Thunder', 'LIGHT', 3, 1200, 1400, '这张卡和对方怪兽进行过战斗的场合，那只怪兽只要在场上表侧表示存在不能攻击。'),
(37829468, 'Rai-Jin', '雷-神', 'RAI－JIN', 'Effect Monster', 'Thunder', 'LIGHT', 4, -1, 1000, '只要这张卡在场上表侧表示存在，自己场上表侧表示存在的光属性怪兽的攻击力上升自己墓地存在的光属性怪兽数量×100的数值。自己的结束阶段时，把自己场上表侧表示存在的1只光属性怪兽破坏。「雷-神」在场上只能有1只表侧表示存在。'),
(63223467, 'Rai-Mei', '雷-鸣', 'RAI－MEI', 'Effect Monster', 'Thunder', 'LIGHT', 3, 1400, 1200, '这张卡被战斗破坏送去墓地时，可以从自己卡组把1只2星以下的光属性怪兽加入手卡。'),
(77558536, 'Raiden, Hand of the Lightsworn', '光道暗杀者 莱丁', 'ライトロード・アサシン ライデン', 'Tuner Monster', 'Warrior', 'LIGHT', 4, 1700, 1000, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。从自己卡组上面把2张卡送去墓地。那之中有「光道」怪兽的场合，再让这张卡的攻击力直到对方回合结束时上升200。 ②：自己结束阶段发动。从自己卡组上面把2张卡送去墓地。'),
(28781003, 'Raider''s Knight', '急袭者骑士', 'レイダーズ・ナイト', 'XYZ Monster', 'Warrior', 'DARK', 4, 2000, NULL, '暗属性4星怪兽×2 这个卡名在规则上也当作「幻影骑士团」卡、「急袭猛禽」卡使用。这个卡名的效果1回合只能使用1次。 ①：把这张卡1个超量素材取除才能发动。比这张卡阶级高1阶或低1阶的「幻影骑士团」、「急袭猛禽」、「超量龙」超量怪兽之内任意1只在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。这个效果特殊召唤的怪兽在下次的对方结束阶段破坏。'),
(87091930, 'Raider''s Unbreakable Mind', '急袭者不屈铁意', 'レイダーズ・アンブレイカブル・マインド', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「幻影骑士团」卡、「急袭猛禽」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：自己作以暗属性超量怪兽为素材的超量召唤成功的场合，以场上1张卡为对象才能发动。那张卡破坏。 ②：魔法与陷阱区域的表侧表示的这张卡被效果破坏的场合才能发动。从自己的卡组·墓地选1张「升阶魔法」魔法卡在自己场上盖放。'),
(52159691, 'Raider''s Wing', '急袭者之翼', 'レイダーズ・ウィング', 'Effect Monster', 'Winged Beast', 'DARK', 4, NULL, 2000, '这个卡名在规则上也当作「幻影骑士团」卡、「急袭猛禽」卡使用。这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，把自己场上的暗属性超量怪兽1个超量素材取除才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：持有这张卡作为素材中的原本属性是暗属性的超量怪兽得到以下效果。 ●这张卡不会成为对方的效果的对象。'),
(96157835, 'Raidraptor - Arsenal Falcon', '急袭猛禽－武库猎鹰', 'RR－アーセナル・ファルコン', 'XYZ Monster', 'Winged Beast', 'DARK', 7, 2500, 2000, '7星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。从卡组把1只鸟兽族·4星怪兽特殊召唤。 ②：持有「急袭猛禽」怪兽作为超量素材的这张卡在同1次的战斗阶段中可以作出最多有那个数量的攻击。 ③：持有「急袭猛禽」怪兽作为超量素材的这张卡被送去墓地的场合才能发动。从额外卡组把「急袭猛禽-武库猎鹰」以外的1只「急袭猛禽」超量怪兽特殊召唤，把这张卡作为那超量素材。'),
(10194329, 'Raidraptor - Avenge Vulture', '急袭猛禽-复仇秃鹫', 'RR－アベンジ・ヴァルチャー', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1700, 100, '①：自己因战斗·效果受到伤害的场合才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是「急袭猛禽」怪兽不能从额外卡组特殊召唤。'),
(96592102, 'Raidraptor - Blade Burner Falcon', '急袭猛禽-火刃焚烧猎鹰', 'RR－ブレード・バーナー・ファルコン', 'XYZ Monster', 'Winged Beast', 'DARK', 4, 1000, 1000, '鸟兽族4星怪兽×2 ①：自己基本分比对方少3000以上，这张卡超量召唤成功的场合才能发动。这张卡的攻击力上升3000。 ②：这张卡战斗破坏对方怪兽时，把这张卡的超量素材任意数量取除才能发动。选取除的超量素材数量的对方场上的怪兽破坏。'),
(45533023, 'Raidraptor - Blaze Falcon', '急袭猛禽－烈焰猎鹰', 'RR－ブレイズ・ファルコン', 'XYZ Monster', 'Winged Beast', 'DARK', 5, 1000, 2000, '鸟兽族5星怪兽×3 ①：持有超量素材的这张卡可以直接攻击。 ②：这张卡给与对方战斗伤害时，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。 ③：1回合1次，把这张卡1个超量素材取除才能发动。对方场上的特殊召唤的怪兽全部破坏，给与对方破坏的怪兽数量×500伤害。'),
(25191307, 'Raidraptor - Bloom Vulture', '急袭猛禽－盛放秃鹫', 'RR－ブルーム・ヴァルチャー', 'Effect Monster', 'Winged Beast', 'DARK', 4, 300, 1900, '这个卡名的①②的效果1回合只能有1次使用其中任意1个，这些效果发动的回合，自己不是暗属性怪兽不能特殊召唤。 ①：自己场上没有鸟兽族怪兽以外的表侧表示怪兽存在的场合才能发动。这张卡和1只「急袭猛禽」怪兽从手卡特殊召唤。 ②：自己场上没有怪兽存在的场合，以包含这张卡的自己墓地2只4星以下的「急袭猛禽」怪兽为对象才能发动。那些怪兽守备表示特殊召唤。'),
(73977033, 'Raidraptor - Booster Strix', '急袭猛禽-推进林鸮', 'RR－ブースター・ストリクス', 'Effect Monster', 'Winged Beast', 'DARK', 4, 100, 1700, '①：自己的「急袭猛禽」怪兽被选择作为对方怪兽的攻击对象时，把这张卡从手卡除外才能发动。那只攻击怪兽破坏。'),
(8617563, 'Raidraptor - Brave Strix', '急袭猛禽－勇猛林鸮', 'RR－ブレイブ・ストリクス', 'XYZ Monster', 'Winged Beast', 'DARK', 5, 2000, 2500, '5星怪兽×2 这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把这张卡1个超量素材取除才能发动。从卡组把1张「急袭猛禽」魔法·陷阱卡在自己场上盖放。 ②：这张卡有鸟兽族怪兽在作为超量素材的场合，把这张卡1个超量素材取除才能发动。从卡组把1张「升阶魔法」魔法卡加入手卡。 ③：持有这张卡作为素材中的「急袭猛禽」超量怪兽得到以下效果。 ●这张卡的攻击力上升自身的阶级×100。'),
(50692511, 'Raidraptor - Call', '急袭猛禽－呼唤', 'RR－コール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「急袭猛禽-呼唤」在1回合只能发动1张，这张卡发动的回合，自己不是「急袭猛禽」怪兽不能特殊召唤。 ①：以自己场上1只「急袭猛禽」怪兽为对象才能发动。那1只同名怪兽从手卡·卡组守备表示特殊召唤。'),
(52323874, 'Raidraptor - Fiend Eagle', '急袭猛禽-恶魔雕', 'RR－デビル・イーグル', 'XYZ Monster', 'Winged Beast', 'DARK', 3, 1000, NULL, '3星「急袭猛禽」怪兽×2 「急袭猛禽-恶魔雕」的效果1回合只能使用1次。 ①：把这张卡1个超量素材取除，以对方场上1只特殊召唤的表侧表示怪兽为对象才能发动。给与对方那只怪兽的原本攻击力数值的伤害。'),
(43047672, 'Raidraptor - Final Fortress Falcon', '急袭猛禽－最终要塞猎鹰', 'RR－ファイナル・フォートレス・ファルコン', 'XYZ Monster', 'Winged Beast', 'DARK', 12, 3800, 2800, '12星怪兽×3 ①：有「急袭猛禽」超量怪兽在作为超量素材中的这张卡不受其他卡的效果影响。 ②：1回合1次，把这张卡1个超量素材取除才能发动。除外的自己的「急袭猛禽」怪兽全部回到墓地。 ③：这张卡的攻击破坏怪兽时，把自己墓地1只「急袭猛禽」超量怪兽除外才能发动。这张卡可以继续攻击。这个效果1回合可以使用最多2次。'),
(73347079, 'Raidraptor - Force Strix', '急袭猛禽－武力林鸮', 'RR－フォース・ストリクス', 'XYZ Monster', 'Winged Beast', 'DARK', 4, 100, 2000, '4星怪兽×2 ①：这张卡的攻击力·守备力上升自己场上的其他的鸟兽族怪兽数量×500。 ②：1回合1次，把这张卡1个超量素材取除才能发动。从卡组把1只鸟兽族·暗属性·4星怪兽加入手卡。'),
(5929801, 'Raidraptor - Fuzzy Lanius', '急袭猛禽－绒雏伯劳', 'RR－ファジー・レイニアス', 'Effect Monster', 'Winged Beast', 'DARK', 4, 500, 1500, '「急袭猛禽-模糊伯劳」的①②的效果1回合各能使用1次，这张卡的效果发动的回合，自己不是「急袭猛禽」怪兽不能特殊召唤。 ①：自己场上有「急袭猛禽-模糊伯劳」以外的「急袭猛禽」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡被送去墓地的场合才能发动。从卡组把1只「急袭猛禽-模糊伯劳」加入手卡。'),
(13927359, 'Raidraptor - Glorious Bright', '急袭猛禽－辉煌荣光', 'RR－グロリアス・ブライト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有「急袭猛禽」怪兽存在的场合，以对方场上1只表侧表示怪兽为对象才能发动（自己场上有「急袭猛禽」超量怪兽存在的场合，也能作为代替以对方场上1张表侧表示卡为对象）。那张卡的效果直到回合结束时无效。 ②：把墓地的这张卡除外，以自己的墓地·除外状态的1只「急袭猛禽」怪兽为对象才能发动。那只怪兽加入手卡。'),
(51933043, 'Raidraptor - Heel Eagle', '急袭猛禽－恶棍猎鹰', 'RR－ヒール・イーグル', 'Effect Monster', 'Winged Beast', 'DARK', 3, 700, 700, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的怪兽只有「急袭猛禽」怪兽的场合才能发动。这张卡从手卡特殊召唤。 ②：把墓地的这张卡除外，以自己墓地1张「急袭猛禽」魔法·陷阱卡为对象才能发动。那张卡加入手卡。'),
(97219708, 'Raidraptor - Last Strix', '急袭猛禽－残存林鸮', 'RR－ラスト・ストリクス', 'Effect Monster', 'Winged Beast', 'DARK', 1, 100, 100, '「急袭猛禽-残存林鸮」的②的效果1回合只能使用1次。 ①：自己的「急袭猛禽」怪兽进行战斗的伤害计算时才能发动。这张卡从手卡特殊召唤。那之后，自己回复自己的场上·墓地的魔法·陷阱卡数量×100基本分。 ②：把这张卡解放才能发动。从额外卡组把1只「急袭猛禽」超量怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段回到额外卡组。这个回合对方受到的战斗伤害变成0。'),
(96345188, 'Raidraptor - Mimicry Lanius', '急袭猛禽－仿声伯劳', 'RR－ミミクリー・レイニアス', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1100, 1900, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的回合的自己主要阶段才能发动1次。自己场上的全部「急袭猛禽」怪兽的等级上升1星。 ②：这张卡被送去墓地的回合的自己主要阶段，把墓地的这张卡除外才能发动。从卡组把「急袭猛禽-模拟伯劳」以外的1张「急袭猛禽」卡加入手卡。'),
(60508057, 'Raidraptor - Napalm Dragonius', '急袭猛禽-汽油弹火龙伯劳', 'RR－ナパーム・ドラゴニアス', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1000, 1000, '①：1回合1次，自己主要阶段才能发动。给与对方600伤害。这个效果的发动后，直到回合结束时自己不能把「急袭猛禽」怪兽以外的怪兽的效果发动。 ②：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只「急袭猛禽」怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(51814159, 'Raidraptor - Necro Vulture', '急袭猛禽－死灵秃鹫', 'RR－ネクロ・ヴァルチャー', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1000, 1600, '①：1回合1次，把自己场上1只「急袭猛禽」怪兽解放，以自己墓地1张「升阶魔法」魔法卡为对象才能发动。那张卡加入手卡。这个效果的发动后，直到回合结束时自己不用「升阶魔法」魔法卡的效果不能把怪兽超量召唤。'),
(8559793, 'Raidraptor - Nest', '急袭猛禽－鸟巢', 'RR－ネスト', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有「急袭猛禽」怪兽2只以上存在的场合才能发动。从自己的卡组·墓地把1只「急袭猛禽」怪兽加入手卡。'),
(99707692, 'Raidraptor - Noir Lanius', '急袭猛禽－漆黑伯劳', 'RR－ノアール・レイニアス', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1600, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的回合的自己主要阶段，以自己场上1只「急袭猛禽」怪兽为对象才能发动。和那只怪兽等级不同的1只「急袭猛禽」怪兽从卡组加入手卡。 ②：把墓地的这张卡除外才能发动。自己场上的「急袭猛禽」怪兽的等级全部上升1星或全部下降1星。'),
(46589034, 'Raidraptor - Pain Lanius', '急袭猛禽－痛苦伯劳', 'RR－ペイン・レイニアス', 'Effect Monster', 'Winged Beast', 'DARK', 1, 100, 100, '这个卡名的效果1回合只能使用1次，把这张卡作为超量召唤的素材的场合，不是鸟兽族怪兽的超量召唤不能使用。 ①：这张卡在手卡存在的场合，以自己场上1只「急袭猛禽」怪兽为对象才能发动。自己受到那只怪兽的攻击力或守备力之内较低方数值的伤害，这张卡特殊召唤。这个效果特殊召唤的这张卡的等级变成和作为对象的怪兽的等级相同。'),
(21648584, 'Raidraptor - Readiness', '急袭猛禽－战备', 'RR－レディネス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合，自己场上的「急袭猛禽」怪兽不会被战斗破坏。 ②：自己墓地有「急袭猛禽」怪兽存在的场合把墓地的这张卡除外才能发动。这个回合，自己受到的全部伤害变成0。'),
(30500113, 'Raidraptor - Return', '急袭猛禽-归来', 'RR－リターン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「急袭猛禽-归来」的②的效果1回合只能使用1次。 ①：自己场上的「急袭猛禽」怪兽被战斗破坏的场合，以自己墓地1只「急袭猛禽」怪兽为对象才能发动。那只怪兽加入手卡。 ②：自己场上的「急袭猛禽」怪兽被效果破坏的场合，把墓地的这张卡除外才能发动。从卡组把1张「急袭猛禽」卡加入手卡。'),
(81927732, 'Raidraptor - Revolution Falcon', '急袭猛禽－革命猎鹰', 'RR－レヴォリューション・ファルコン', 'XYZ Monster', 'Winged Beast', 'DARK', 6, 2000, 3000, '鸟兽族6星怪兽×3 ①：把这张卡1个超量素材取除才能发动。这个回合，这张卡可以向对方怪兽全部各作1次攻击。 ②：这张卡和特殊召唤的表侧表示怪兽进行战斗的伤害步骤开始时发动。那只怪兽的攻击力·守备力变成0。 ③：这张卡有「急袭猛禽」超量怪兽在作为超量素材的场合，得到以下效果。 ●1回合1次，以对方场上1只怪兽为对象才能发动。那只怪兽破坏，给与对方那个攻击力一半数值的伤害。'),
(79985120, 'Raidraptor - Revolution Falcon - Air Raid', '急袭猛禽－革命猎鹰－大空袭', 'RR－レヴォリューション・ファルコン－エアレイド', 'XYZ Monster', 'Winged Beast', 'DARK', 6, 2000, 3000, '鸟兽族6星怪兽×3 这张卡也能把手卡1张「升阶魔法」魔法卡丢弃，在自己场上的5阶以下的「急袭猛禽」超量怪兽上面重叠来超量召唤。 ①：这张卡超量召唤的场合，以对方场上1只怪兽为对象才能发动。那只怪兽破坏，给与对方那个攻击力数值的伤害。 ②：这张卡被对方破坏送去墓地的场合才能发动。从额外卡组把1只「急袭猛禽-革命猎鹰」特殊召唤，把这张卡作为超量素材。'),
(73887236, 'Raidraptor - Rise Falcon', '急袭猛禽－起升猎鹰', 'RR－ライズ・ファルコン', 'XYZ Monster', 'Winged Beast', 'DARK', 4, 100, 2000, '鸟兽族4星怪兽×3 ①：这张卡可以向特殊召唤的对方怪兽全部各作1次攻击。 ②：1回合1次，把这张卡1个超量素材取除，以对方场上1只特殊召唤的怪兽为对象才能发动。这张卡的攻击力上升作为对象的怪兽的攻击力数值。'),
(71222868, 'Raidraptor - Rising Rebellion Falcon', '急袭猛禽－起升反叛猎鹰', 'RR－ライジング・リベリオン・ファルコン', 'XYZ Monster', 'Winged Beast', 'DARK', 13, 4000, 3500, '鸟兽族13星怪兽×5 ①：这张卡超量召唤的场合才能发动。对方场上的卡全部破坏。那之后，这张卡有「急袭猛禽」超量怪兽3种类以上在作为素材的场合，给与对方这个效果破坏的怪兽的原本攻击力合计数值的伤害。 ②：场上的这张卡不受其他卡的效果影响。 ③：1回合1次，把这张卡3个超量素材取除，以自己墓地1只「急袭猛禽」超量怪兽为对象才能发动。直到结束阶段，这张卡得到和那只怪兽相同的效果。'),
(64049553, 'Raidraptor - Roost', '急袭猛禽－栖地', 'RR－ルースト', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：「急袭猛禽」怪兽从额外卡组往自己场上特殊召唤的场合才能发动。从卡组把「急袭猛禽-鸟窝」以外的1张「急袭猛禽」魔法·陷阱卡加入手卡。 ②：以自己的墓地·除外状态的3只「急袭猛禽」怪兽为对象才能发动。那些怪兽用喜欢的顺序回到卡组下面。那之后，自己抽1张。'),
(6552938, 'Raidraptor - Rudder Strix', '急袭猛禽-方向舵林鸮', 'RR－ラダー・ストリクス', 'Effect Monster', 'Winged Beast', 'DARK', 4, NULL, 1600, '①：这张卡召唤成功的场合或者用「急袭猛禽」卡的效果从手卡特殊召唤成功的场合才能发动。给与对方600伤害。 ②：这张卡为攻击对象的对方怪兽的攻击宣言时才能发动。从手卡把最多2只「急袭猛禽」怪兽特殊召唤。这个回合，对方不能选择这个效果特殊召唤的怪兽作为攻击对象。'),
(23603403, 'Raidraptor - Satellite Cannon Falcon', '急袭猛禽－卫星炮猎鹰', 'RR－サテライト・キャノン・ファルコン', 'XYZ Monster', 'Winged Beast', 'DARK', 8, 3000, 2000, '鸟兽族8星怪兽×2 ①：这张卡用「急袭猛禽」怪兽为素材作超量召唤成功的场合才能发动。对方场上的魔法·陷阱卡全部破坏。对方不能对应这个效果的发动把魔法·陷阱·怪兽的效果发动。 ②：把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力下降自己墓地的「急袭猛禽」怪兽数量×800。这个效果在对方回合也能发动。'),
(60950180, 'Raidraptor - Sharp Lanius', '急袭猛禽-穿刺伯劳', 'RR－インペイル・レイニアス', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1700, 1000, '「急袭猛禽-穿刺伯劳」的②的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的回合的自己主要阶段只有1次，以场上1只表侧攻击表示怪兽为对象才能发动。那只怪兽变成表侧守备表示。 ②：这张卡攻击过的回合的自己主要阶段2，以自己墓地1只「急袭猛禽」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(31314549, 'Raidraptor - Singing Lanius', '急袭猛禽－鸣啭伯劳', 'RR－シンギング・レイニアス', 'Effect Monster', 'Winged Beast', 'DARK', 4, 100, 100, '「急袭猛禽-鸣啭伯劳」的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有超量怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(45184165, 'Raidraptor - Skull Eagle', '急袭猛禽-骷髅雕', 'RR－スカル・イーグル', 'Effect Monster', 'Winged Beast', 'DARK', 3, 1000, 500, '「急袭猛禽-骷髅雕」的①的效果1回合只能使用1次。 ①：超量素材的这张卡为让超量怪兽的效果发动而被取除送去墓地的场合，把墓地的这张卡除外，以自己墓地1张「急袭猛禽」卡为对象才能发动。那张卡加入手卡。 ②：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这次超量召唤成功的场合发动。这张卡的攻击力上升300。'),
(15092394, 'Raidraptor - Stranger Falcon', '急袭猛禽－异邦猎鹰', 'RR－エトランゼ・ファルコン', 'XYZ Monster', 'Winged Beast', 'DARK', 5, 2000, 2000, '5星怪兽×2 ①：这张卡有超量怪兽在作为超量素材的场合，得到以下效果。 ●1回合1次，把这张卡1个超量素材取除，以对方场上1只怪兽为对象才能发动。那只怪兽破坏，给与对方那个原本攻击力数值的伤害。 ②：这张卡被对方破坏送去墓地的场合，以「急袭猛禽-异邦猎鹰」以外的自己墓地1只「急袭猛禽」超量怪兽为对象才能发动。那只怪兽特殊召唤，把这张卡在那张卡下面重叠作为超量素材。'),
(87321742, 'Raidraptor - Strangle Lanius', '急袭猛禽－绞杀伯劳', 'RR－ストラングル・レイニアス', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1600, 1100, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有暗属性怪兽存在的场合才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是暗属性怪兽不能特殊召唤。 ②：自己场上有用暗属性超量怪兽在作为超量素材中的超量怪兽存在的场合，以自己墓地1只4星以下的「急袭猛禽」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(83236601, 'Raidraptor - Tribute Lanius', '急袭猛禽－献祭伯劳', 'RR－トリビュート・レイニアス', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1800, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的回合的自己主要阶段才能发动。从卡组把1张「急袭猛禽」卡送去墓地。 ②：这张卡战斗破坏对方怪兽的回合的自己主要阶段2才能发动。从卡组把1张「升阶魔法」速攻魔法卡加入手卡。这个效果的发动后，直到回合结束时自己不是「急袭猛禽」怪兽不能特殊召唤。'),
(86221741, 'Raidraptor - Ultimate Falcon', '急袭猛禽－究极猎鹰', 'RR－アルティメット・ファルコン', 'XYZ Monster', 'Winged Beast', 'DARK', 10, 3500, 2000, '鸟兽族10星怪兽×3 ①：场上的这张卡不受其他卡的效果影响。 ②：把这张卡1个超量素材取除才能发动。这个回合中，对方场上的怪兽的攻击力下降1000，对方不能把卡的效果发动。 ③：这张卡有「急袭猛禽」怪兽在作为超量素材的场合，得到以下效果。 ●自己·对方的结束阶段才能发动。对方场上有表侧表示怪兽存在的场合，那些攻击力下降1000。不存在的场合，给与对方1000伤害。'),
(53251824, 'Raidraptor - Vanishing Lanius', '急袭猛禽－消绝伯劳', 'RR－バニシング・レイニアス', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1300, 1600, '①：这张卡召唤·特殊召唤的回合的自己主要阶段才能发动1次。从手卡把1只4星以下的「急袭猛禽」怪兽特殊召唤。'),
(8785161, 'Raidraptor - Wild Vulture', '急袭猛禽-荒野秃鹫', 'RR－ワイルド・ヴァルチャー', 'Effect Monster', 'Winged Beast', 'DARK', 6, 1600, 2000, '①：这张卡召唤·特殊召唤成功的回合的自己主要阶段把这张卡解放才能发动。等级合计直到变成6星为止，从自己的手卡·墓地选2只「急袭猛禽」怪兽特殊召唤。'),
(36429703, 'Raidraptor - Wise Strix', '急袭猛禽－智慧林鸮', 'RR－ワイズ・ストリクス', 'Link Monster', 'Winged Beast', 'DARK', NULL, 1400, NULL, '鸟兽族·暗属性怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组把1只鸟兽族·暗属性·4星怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽不能作为连接素材，效果无效化。 ②：自己的「急袭猛禽」超量怪兽的效果发动的场合发动。从卡组把1张「升阶魔法」魔法卡在自己场上盖放。把速攻魔法卡盖放的场合，那张卡在盖放的回合也能发动。'),
(54423935, 'Raidraptor Replica', '急袭猛禽复制品', 'R・R・R', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡在规则上也当作「急袭猛禽」卡使用。 ①：以自己场上1只「急袭猛禽」怪兽为对象才能发动。那1只同名怪兽从卡组特殊召唤。只要这个效果特殊召唤的怪兽在自己场上表侧表示存在，对方不能把作为对象的怪兽作为攻击对象，也不能作为效果的对象。'),
(13486638, 'Raidraptor''s Phantom Knights Claw', '急袭猛禽－魅影爪', 'RR－ファントム・クロー', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：怪兽的效果发动时，把自己场上的暗属性超量怪兽1个超量素材取除才能发动。那个发动无效并破坏。为这张卡发动而取除的超量素材是「幻影骑士团」、「急袭猛禽」、「超量龙」卡的场合，再选自己场上1只「急袭猛禽」超量怪兽，那个攻击力上升这个效果破坏的怪兽的原本攻击力数值。'),
(12580477, 'Raigeki', '雷击', 'サンダー・ボルト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上的怪兽全部破坏。'),
(11741041, 'Raigeki Bottle', '雷瓶', 'サンダー・ボトル', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己场上存在的怪兽攻击宣言，给这张卡放置1个雷指示物。可以把有雷指示物4个以上放置的这张卡送去墓地，对方场上存在的怪兽全部破坏。'),
(4178474, 'Raigeki Break', '雷破', 'サンダー・ブレイク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：丢弃1张手卡，以场上1张卡为对象才能发动。那张卡破坏。'),
(99991455, 'Raijin the Breakbolt Star', '霸雷星 雷神', '覇雷星ライジン', 'Fusion Monster', 'Warrior', 'LIGHT', 10, 3000, 2200, '5星以上的战士族·光属性怪兽＋战士族·地属性怪兽 这个卡名的③的效果1回合只能使用1次。 ①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ②：这张卡用和不持有等级的怪兽的战斗给与对方的战斗伤害变成2倍。 ③：这张卡被战斗·效果破坏送去墓地的回合的结束阶段，以自己墓地2只7星以下的战士族怪兽为对象才能发动。那些怪兽特殊召唤。'),
(56260110, 'Raimei', '雷鸣', '雷鳴', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方受到300分的伤害。'),
(95568112, 'Rain Bozu', '雨天虹娃', 'レイン・ボーズ', 'Pendulum Effect Monster', 'Fairy', 'LIGHT', 7, NULL, NULL, '①：这张卡在自己回合内是攻击力，在对方回合内是守备力，上升双方的额外卡组的数量差×200。 ②：这张卡攻击的场合，战斗阶段结束时变成守备表示。 ③：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(101303086, 'Rain of Frogs', NULL, NULL, 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(66719324, 'Rain of Mercy', '恩惠之雨', '恵みの雨', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '双方的基本分回复1000分。'),
(45653036, 'Rain Storm', '暴风雨', '暴風雨', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「云魔物」的怪兽发动。把选择怪兽的攻击力下降，以下效果适用。 ●下降1000：对方场上1张魔法或者陷阱卡破坏。 ●下降2000：对方场上2张卡破坏。'),
(63945693, 'Rainbow Bridge', '虹之桥梁', '虹の架け橋', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1张「宝玉」魔法·陷阱卡加入手卡。'),
(5611760, 'Rainbow Bridge of Salvation', '拯救的桥梁', '救いの架け橋', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果在决斗中各能适用1次。 ①：场上的10星以上的怪兽的种族是2种类以上的场合才能发动。这张卡以外的双方的手卡·场上·墓地的卡全部回到持有者卡组。那之后，双方从卡组抽5张。 ②：把墓地的这张卡除外才能发动。从卡组把1只「宝玉兽」怪兽和1张场地魔法卡加入手卡。'),
(10938846, 'Rainbow Bridge of the Heart', '心之桥梁', '心の架け橋', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：自己在通常召唤外加上只有1次，自己主要阶段可以把1只「宝玉兽」怪兽召唤。 ②：自己主要阶段才能发动。选自己的手卡·场上1张「宝玉兽」卡破坏，从卡组把1张「宝玉」魔法·陷阱卡加入手卡。 ③：自己的魔法与陷阱区域有「宝玉兽」卡被放置的场合，以对方场上1张卡为对象才能发动（伤害步骤也能发动）。那张卡和这张卡回到持有者手卡。'),
(300302038, 'Rainbow Crystal Collection', NULL, NULL, 'Skill Card', 'Jesse Anderso', NULL, NULL, NULL, NULL, NULL),
(79407975, 'Rainbow Dark Dragon', '究极宝玉神 彩虹暗黑龙', '究極宝玉神 レインボー・ダーク・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 10, 4000, NULL, '这张卡不能通常召唤。从自己墓地把暗属性怪兽7种类各1只除外的场合才能特殊召唤。 ①：从自己墓地以及自己场上的表侧表示怪兽之中把这张卡以外的暗属性怪兽全部除外才能发动。这张卡的攻击力上升除外数量×500。'),
(79856792, 'Rainbow Dragon', '究极宝玉神 彩虹龙', '究極宝玉神 レインボー・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 10, 4000, NULL, '这张卡不能通常召唤。自己的场上·墓地是「宝玉兽」卡7种类存在的场合才能特殊召唤。这张卡特殊召唤的回合，这张卡的①②的效果不能发动。 ①：把自己场上的表侧表示的「宝玉兽」怪兽全部送去墓地才能发动。这张卡的攻击力上升送去墓地的怪兽数量×1000。这个效果在对方回合也能发动。 ②：从自己墓地把「宝玉兽」怪兽全部除外才能发动。场上的卡全部回到持有者卡组。'),
(21347810, 'Rainbow Flower', '彩虹花', 'レインボー・フラワー', 'Effect Monster', 'Plant', 'EARTH', 2, 400, 500, '这张卡可以直接攻击对方玩家。'),
(63806265, 'Rainbow Gravity', '虹之引力', '虹の引力', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己的场上以及墓地名字带有「宝玉兽」的卡合计7种类存在的场合才能发动。把自己的卡组或者墓地存在的1只名字带有「究极宝玉神」的怪兽无视召唤条件特殊召唤。'),
(2830693, 'Rainbow Kuriboh', '虹库里波', '虹クリボー', 'Effect Monster', 'Fiend', 'LIGHT', 1, 100, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：对方怪兽的攻击宣言时，以那1只攻击怪兽为对象才能发动。这张卡从手卡当作装备卡使用给那只怪兽装备。装备怪兽不能攻击。 ②：这张卡在墓地存在的场合，对方怪兽的直接攻击宣言时才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(34002992, 'Rainbow Life', '虹之生命', 'レインボー・ライフ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '丢弃1张手卡才能发动。直到这个回合的结束阶段时，自己作为因战斗以及卡的效果受到伤害的代替而回复那个数值的基本分。'),
(29402771, 'Rainbow Marine Mermaid', '彩虹人鱼', 'レインボー・マリン・マーメイド', 'Normal Monster', 'Fish', 'WATER', 5, 1550, 1700, '空中出现彩虹桥时才会出现的珍奇美丽人鱼。'),
(86346643, 'Rainbow Neos', '彩虹新宇侠', 'レインボー・ネオス', 'Fusion Monster', 'Warrior', 'LIGHT', 10, 4500, 3000, '「元素英雄 新宇侠」＋「究极宝玉神」怪兽 这张卡用以上记的卡为融合素材的融合召唤才能特殊召唤。 ①：1回合1次，可以从以下效果选择1个发动。 ●把自己场上1只怪兽送去墓地才能发动。对方场上的怪兽全部回到持有者卡组。 ●把自己场上1张魔法·陷阱卡送去墓地才能发动。对方场上的魔法·陷阱卡全部回到持有者卡组。 ●把卡组最上面的卡送去墓地才能发动。对方墓地的卡全部回到卡组。'),
(37440988, 'Rainbow Overdragon', '究极宝玉神 虹桥龙', '究極宝玉神 レインボー・オーバー・ドラゴン', 'Fusion Monster', 'Dragon', 'LIGHT', 12, 4000, NULL, '「宝玉兽」怪兽×7 这张卡用融合召唤以及以下方法才能特殊召唤。 ●把自己场上1只10星「究极宝玉神」怪兽解放的场合可以从额外卡组特殊召唤。 ①：1回合1次，从自己墓地把1只「宝玉兽」怪兽除外才能发动。这张卡的攻击力直到回合结束时上升除外的怪兽的攻击力数值。 ②：把融合召唤的这张卡解放才能发动。场上的卡全部回到持有者卡组。这个效果在对方回合也能发动。'),
(7617253, 'Rainbow Path', '虹之行方', '虹の行方', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时，选择自己的魔法与陷阱卡区域存在的1张名字带有「宝玉兽」的卡送去墓地发动。可以把1只对方怪兽的攻击无效，从自己卡组选择1张名字带有「究极宝玉神」的卡加入手卡。'),
(40854824, 'Rainbow Refraction', '飞越虹桥', 'オーバー・ザ・レインボー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：原本卡名是「究极宝玉神 虹龙」或者「究极宝玉神 虹暗龙」的怪兽在自己场上把效果发动的回合才能发动。从卡组把「宝玉兽」怪兽任意数量特殊召唤（同名卡最多1张）。'),
(12735388, 'Rainbow Veil', '虹之衣', 'レインボー・ヴェール', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽和对方怪兽进行战斗的场合，只在战斗阶段内那只对方怪兽的效果无效化。'),
(51267887, 'Raise Body Heat', '体温上升', '体温の上昇', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '恐龙族怪兽可以装备。装备怪兽的攻击力·守备力上升300。'),
(69327790, 'Raiza the Mega Monarch', '烈风帝莱萨', '烈風帝ライザー', 'Effect Monster', 'Winged Beast', 'WIND', 8, 2800, 1000, '这张卡可以把1只上级召唤的怪兽解放作上级召唤。 ①：这张卡上级召唤成功的场合，以场上1张卡和自己或者对方的墓地1张卡为对象发动。那些卡用喜欢的顺序回到持有者卡组最上面。这张卡把风属性怪兽解放作上级召唤成功的场合，那个时候的效果加上以下效果。 ●可以以场上1张卡为对象回到持有者手卡。'),
(73125233, 'Raiza the Storm Monarch', '风帝莱萨', '風帝ライザー', 'Effect Monster', 'Winged Beast', 'WIND', 6, 2400, 1000, '①：这张卡上级召唤的场合，以场上1张卡为对象发动。那张卡回到卡组最上面。'),
(41382147, 'Rallis the Star Bird', '星见鸟 拉里斯', '星見鳥ラリス', 'Effect Monster', 'Winged Beast', 'WIND', 3, 800, 800, '这张卡的攻击力在伤害步骤时上升战斗的对方怪兽等级×200的数值。这张卡攻击的场合伤害步骤结束时从游戏中除外，下次自己回合的战斗阶段开始时表侧攻击表示回到自己场上。'),
(9190563, 'RAM Clouder', 'RAM云雄羊', 'RAMクラウダー', 'Effect Monster', 'Cyberse', 'LIGHT', 4, 1800, 1000, '这个卡名的效果1回合只能使用1次。 ①：把自己场上1只怪兽解放，以自己墓地1只电子界族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(3784434, 'Rampaging Rhynos', '突击犀牛', '突撃ライノス', 'Effect Monster', 'Beast-Warrior', 'EARTH', 3, 1500, 1500, '1回合1次，指定没有使用的相邻的怪兽卡区域才能发动。自己场上的这张卡向那个怪兽卡区域移动。向这张卡的正对面的对方怪兽攻击的场合，伤害步骤内这张卡的攻击力上升500。'),
(82197831, 'Rampaging Smashtank Rhynosaber', '蓦进装甲 犀牛军刀', '驀進装甲ライノセイバー', 'Synchro Monster', 'Machine', 'FIRE', 7, 2400, 2100, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：把手卡任意数量丢弃才能发动。这张卡的攻击力上升丢弃数量×700。 ②：这张卡进行战斗的战斗阶段结束时，把这张卡送去墓地才能发动。等级合计直到变成7星为止，从自己墓地选「蓦进装甲 剑角犀牛」以外的怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(71345905, 'Rank-Down-Magic Numeron Fall', '降阶魔法－源数之落', 'RDM－ヌメロン・フォール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1只名字带有「希望皇 霍普」的怪兽才能发动。比选择的怪兽阶级低的1只名字带有「希望皇 霍普」的怪兽在选择的自己怪兽上面重叠当作超量召唤从额外卡组特殊召唤。这个效果超量召唤的怪兽得到以下效果。 ●这张卡和对方怪兽进行战斗的场合，只在战斗阶段内那只对方怪兽的效果无效化。'),
(57734012, 'Rank-Up-Magic - The Seventh One', '升阶魔法－七皇之剑', 'RUM－七皇の剣', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的效果在决斗中只能适用1次。 ①：自己抽卡阶段通过把通常抽卡的这张卡持续公开，那个回合的主要阶段1开始时才能发动。从自己的额外卡组·墓地选「混沌No.」怪兽以外的1只「No.101」～「No.107」其中任意种的「No.」怪兽特殊召唤，把持有和那只怪兽相同「No.」数字的1只「混沌No.」怪兽在那只怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(96142517, 'Rank-Up-Magic Admiration of the Thousands', '升阶魔法-千死蛮巧', 'RUM－千死蛮巧', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「升阶魔法-千死蛮巧」在1回合只能发动1张，这张卡发动的回合，自己不能用这张卡的效果以外把怪兽特殊召唤。 ①：以自己以及对方的墓地的相同阶级的超量怪兽各1只以上为对象才能发动。比那些怪兽阶级高1阶的1只「混沌No.」怪兽或者「混沌超量」怪兽从额外卡组特殊召唤，把作为对象的怪兽在下面重叠作为超量素材。'),
(94220427, 'Rank-Up-Magic Argent Chaos Force', '升阶魔法－紧急混沌之力', 'RUM－アージェント・カオス・フォース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果在决斗中只能使用1次。 ①：以自己场上1只5阶以上的超量怪兽为对象才能发动。比那只自己怪兽阶级高1阶的1只「混沌No.」怪兽或「混沌超量」怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。 ②：这张卡在墓地存在的状态，自己场上有5阶以上的超量怪兽特殊召唤时才能发动。这张卡加入手卡。'),
(45950291, 'Rank-Up-Magic Astral Force', '升阶魔法－阿斯特拉尔之力', 'RUM－アストラル・フォース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只阶级最高的超量怪兽为对象才能发动。和那只自己怪兽相同种族·属性而阶级高2阶的1只怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。 ②：这张卡在墓地存在的场合，自己抽卡阶段的抽卡前才能发动。这张卡加入手卡。这个效果发动的回合，自己不能进行通常抽卡，不能用「升阶魔法-星光之力」的效果以外把怪兽特殊召唤。'),
(47660516, 'Rank-Up-Magic Barian''s Force', '升阶魔法－巴利安之力', 'RUM－バリアンズ・フォース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只超量怪兽为对象才能发动。和那只自己怪兽相同种族而阶级高1阶的1只「混沌No.」怪兽或「混沌超量」怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。对方场上有超量素材存在的场合，再把那之内的1个作为那只特殊召唤的怪兽的超量素材。'),
(47882565, 'Rank-Up-Magic Cipher Ascension', '升阶魔法－光波升华', 'RUM－光波昇華', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己·对方的主要阶段，以自己场上1只「光波」超量怪兽为对象才能发动。比那只自己怪兽阶级高1阶的1只「光波」超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。这个效果特殊召唤的怪兽得到以下效果。 ●这张卡的攻击力上升自己场上的4星以上的怪兽数量×500。'),
(86196216, 'Rank-Up-Magic Doom Double Force', '升阶魔法－死亡双力', 'RUM－デス・ダブル・フォース', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以这个回合被战斗破坏送去自己墓地的1只「急袭猛禽」超量怪兽为对象才能发动。那只怪兽特殊召唤，那只怪兽的2倍阶级的1只超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(92365601, 'Rank-Up-Magic Limited Barian''s Force', '升阶魔法－限制型巴利安之力', 'RUM－リミテッド・バリアンズ・フォース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1只4阶的超量怪兽才能发动。比选择的怪兽阶级高1阶的1只名字带有「混沌No.」的怪兽在选择的自己怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(32044231, 'Rank-Up-Magic Magical Force', '升阶魔法－魔术之力', 'RUM－マジカル・フォース', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只魔法师族·4阶的超量怪兽为对象才能发动。那只怪兽效果无效特殊召唤，把1只魔法师族·5阶的超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤，把这张卡作为那超量素材。'),
(48333324, 'Rank-Up-Magic Numeron Force', '升阶魔法－源数之力', 'RUM－ヌメロン・フォース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只超量怪兽为对象才能发动。和那只自己怪兽相同种族而阶级高1阶的1只「混沌No.」怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。那之后，这个效果特殊召唤的怪兽以外的场上的全部表侧表示的卡的效果无效化。'),
(33252803, 'Rank-Up-Magic Quick Chaos', '升阶魔法－速攻混沌', 'RUM－クイック・カオス', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以「混沌No.」怪兽以外的自己场上1只「No.」超量怪兽为对象才能发动。比那只自己怪兽阶级高1阶并持有相同「No.」数字的1只「混沌No.」怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(41201386, 'Rank-Up-Magic Raid Force', '升阶魔法－急袭之力', 'RUM－レイド・フォース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只超量怪兽为对象才能发动。比那只怪兽阶级高1阶的1只「急袭猛禽」怪兽在作为对象的自己怪兽上面重叠当作超量召唤从额外卡组特殊召唤。 ②：把墓地的这张卡和手卡1张「急袭猛禽」卡除外，以「升阶魔法-急袭之力」以外的自己墓地1张「升阶魔法」魔法卡为对象才能发动。那张卡加入手卡。'),
(43383478, 'Rank-Up-Magic Raptor''s Force', '升阶魔法-猛禽之力', 'RUM－ラプターズ・フォース', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上的「急袭猛禽」超量怪兽被破坏送去墓地的回合，以自己墓地1只「急袭猛禽」超量怪兽为对象才能发动。那只怪兽特殊召唤，比那只怪兽阶级高1阶的1只「急袭猛禽」怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(43476205, 'Rank-Up-Magic Revolution Force', '升阶魔法-革命之力', 'RUM－レヴォリューション・フォース', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以把发动回合的以下效果发动。 ●自己回合：以自己场上1只「急袭猛禽」超量怪兽为对象才能发动。阶级高1阶的1只「急袭猛禽」怪兽在作为对象的自己怪兽上面重叠当作超量召唤从额外卡组特殊召唤。 ●对方回合：以对方场上1只没有超量素材的超量怪兽为对象才能发动。得到那只超量怪兽的控制权。那之后，阶级高1阶的1只「急袭猛禽」怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(58988903, 'Rank-Up-Magic Skip Force', '升阶魔法－跳级之力', 'RUM－スキップ・フォース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「急袭猛禽」超量怪兽为对象才能发动。比那只怪兽阶级高2阶的1只「急袭猛禽」怪兽在作为对象的自己怪兽上面重叠当作超量召唤从额外卡组特殊召唤。 ②：从自己墓地把这张卡和1只「急袭猛禽」怪兽除外，以自己墓地1只「急袭猛禽」超量怪兽为对象才能发动。那只怪兽特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(23581825, 'Rank-Up-Magic Soul Shave Force', '升阶魔法－削魂之力', 'RUM－ソウル・シェイブ・フォース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把基本分支付一半，以自己墓地1只「急袭猛禽」超量怪兽为对象才能发动。那只怪兽特殊召唤，比那只怪兽阶级高2阶的1只超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(36224040, 'Rank-Up-Magic Zexal Force', '升阶魔法－ZEXAL之力', 'RUM－ゼアル・フォース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己场上1只超量怪兽为对象才能发动。比那只自己怪兽阶级高1阶的1只「希望皇 霍普」怪兽或者「异热同心武器」怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤，从卡组选1只「异热同心武器」怪兽或者「异热同心从者」怪兽在卡组最上面放置。 ②：自己基本分比对方少2000以上的场合，把墓地的这张卡除外才能发动。自己从卡组抽1张。'),
(44680819, 'Ranryu', '岚龙', 'ランリュウ', 'Effect Monster', 'Dragon', 'WIND', 4, 1500, 200, '①：「岚龙」在自己场上只能有1张表侧表示存在。 ②：自己场上有魔法师族怪兽存在的场合，这张卡可以从手卡特殊召唤。 ③：这张卡被战斗·效果破坏送去墓地的场合，以除「岚龙」外的自己墓地1只攻击力1500/守备力200的怪兽为对象才能发动。那只怪兽特殊召唤。'),
(60222213, 'Raphion, the Timelord', '时械神 拉法恩', '時械神ラフィオン', 'Effect Monster', 'Fairy', 'WIND', 10, NULL, NULL, '这张卡不能从卡组特殊召唤。 ①：自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡不会被战斗·效果破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ③：这张卡进行战斗的战斗阶段结束时发动。选这个回合和这张卡进行过战斗的对方场上1只表侧表示怪兽，给与对方那个攻击力数值的伤害。 ④：自己准备阶段发动。这张卡回到持有者卡组。'),
(67526112, 'Rapid Trigger', '旋疾扳机', 'ラピッド・トリガー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：融合怪兽卡决定的自己场上的融合素材怪兽破坏，把那1只融合怪兽从额外卡组融合召唤。这个效果特殊召唤的怪兽只能向从额外卡组特殊召唤的怪兽攻击，不受从额外卡组特殊召唤的其他怪兽发动的效果影响。'),
(255998, 'Rapid Warrior', '疾速战士', 'ラピッド・ウォリアー', 'Effect Monster', 'Warrior', 'WIND', 4, 1200, 200, '主要阶段1才能发动。这个回合这张卡可以直接攻击对方玩家。这个效果发动的回合，这张卡以外的怪兽不能攻击。'),
(6337436, 'Rapid-Fire Magician', '连弹之魔术师', '連弾の魔術師', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1600, 1200, '只要这张卡在场上表侧表示存在，每次自己发动通常魔法卡，给与对方基本分400分的伤害。'),
(94681654, 'Raptor Wing Strike', '羽风攻击', 'フェザー・ウィンド・アタック', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '让自己场上表侧表示存在的1只名字带有「黑羽」的怪兽回到卡组发动。从自己卡组把1只名字带有「黑羽」的怪兽加入手卡。'),
(66994718, 'Raptor''s Gust', '猛禽突风', 'ラプターズ・ガスト', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己场上有「急袭猛禽」卡存在，魔法·陷阱卡发动时才能发动。那个发动无效并破坏。'),
(87609391, 'Raptor''s Ultimate Mace', '猛禽究极硬头锤', 'ラプターズ・アルティメット・メイス', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「急袭猛禽」怪兽才能装备。 ①：装备怪兽的攻击力上升1000。 ②：装备怪兽被选择作为比装备怪兽攻击力高的怪兽的攻击对象时才能发动。从卡组把1张「升阶魔法」魔法卡加入手卡，那次战斗发生的对自己的战斗伤害变成0。'),
(80516007, 'Rare Fish', '珍鱼', 'レア・フィッシュ', 'Fusion Monster', 'Fish', 'WATER', 4, 1500, 1200, '「融合体」＋「恍惚的人鱼」'),
(25236056, 'Rare Metal Dragon', '稀有金属龙', 'レアメタル・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 4, 2400, 1200, '这张卡不能通常召唤，用卡的效果才能特殊召唤。'),
(12503902, 'Rare Metalmorph', '稀有金属化·魔法反射装甲', 'レアメタル化・魔法反射装甲', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择场上表侧表示存在的1只机械族怪兽发动。选择的怪兽的攻击力上升500，那只怪兽为对象的魔法卡的效果只有1次无效。那只怪兽从场上离开时这张卡破坏。'),
(60876124, 'Rare Value', '珍稀价值', 'レア・ヴァリュー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的魔法与陷阱区域有「宝玉兽」卡2张以上存在的场合才能发动。自己的魔法与陷阱区域1张「宝玉兽」卡由对方选出。对方选的卡送去墓地，自己从卡组抽2张。'),
(7625614, 'Raregold Armor', '贵金铠甲', 'レアゴールド・アーマー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '只要控制装备这张卡的怪兽，对方不能攻击装备怪兽以外的怪兽。'),
(18716735, 'Raremetalfoes Bismugear', '稀炼装勇士·铋巫', 'レアメタルフォーゼ・ビスマギア', 'Pendulum Effect Monster', 'Psychic', 'FIRE', 1, NULL, NULL, '这个卡名的怪兽效果1回合只能使用1次。 ①：场上的这张卡被战斗·效果破坏的场合才能发动。这个回合的结束阶段，从卡组把1只「炼装」怪兽加入手卡。'),
(43378076, 'Rasetsu', '罗刹', '羅刹', 'Spirit Monster', 'Fairy', 'FIRE', 4, 1500, 1900, '这张卡不能特殊召唤。召唤·反转的回合的结束阶段时回到持有者手卡。这张卡召唤·反转时，把「罗刹」以外的手卡1只灵魂怪兽给对方观看才能发动。选择对方场上表侧攻击表示存在的1只怪兽回到持有者手卡。这个效果发动的回合，自己不能把怪兽特殊召唤。'),
(88000953, 'Rasterliger', '光栅狮虎', 'ラスタライガー', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 2000, NULL, '衍生物以外的怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：以自己或者对方的墓地1只连接怪兽为对象才能发动。这张卡的攻击力直到回合结束时上升那只怪兽的攻击力数值。 ②：把这张卡所连接区的自己怪兽任意数量解放才能发动。选解放的怪兽数量的场上的卡破坏。'),
(87188910, 'Ravenous Crocodragon Archethys', '饥鳄龙 饿古提斯', '飢鰐竜アーケティス', 'Synchro Monster', 'Fish', 'WATER', 9, 1000, 1000, '调整＋调整以外的怪兽1只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。自己抽出那些作为同调素材的怪兽之内除调整以外的怪兽的数量。 ②：这张卡的攻击力·守备力上升自己手卡数量×500。 ③：自己·对方回合，丢弃2张手卡，以场上1张卡为对象才能发动。那张卡破坏。'),
(13386407, 'Ravenous Vendread', '极饿・仇尸', 'ラヴェナス・ヴェンデット', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「复仇死者」仪式怪兽的降临必需。这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·卡组·墓地选「复仇死者·噬腐鬼」以外的1只「复仇死者」怪兽里侧守备表示特殊召唤。那之后，以下效果适用。 ●等级合计直到变成仪式召唤的怪兽的等级以上为止，把包含这个效果特殊召唤的怪兽的自己场上的怪兽解放，从自己的手卡·墓地把1只「复仇死者」仪式怪兽仪式召唤。'),
(69890967, 'Raviel, Lord of Phantasms', '幻魔皇拉比艾尔', '幻魔皇ラビエル', 'Effect Monster', 'Fiend', 'DARK', 10, 4000, 4000, '这张卡不能通常召唤。把自己场上3只恶魔族怪兽解放的场合才能特殊召唤。 ①：1回合1次，把这张卡以外的自己场上1只怪兽解放才能发动。这张卡的攻击力直到回合结束时上升解放的怪兽的原本攻击力数值。 ②：对方对怪兽的召唤成功的场合发动。在自己场上把1只「幻魔衍生物」（恶魔族·暗·1星·攻/守1000）特殊召唤。这衍生物不能攻击宣言。'),
(28651380, 'Raviel, Lord of Phantasms - Shimmering Scraper', '幻魔皇拉比艾尔－天界蹂躏拳', '幻魔皇ラビエル－天界蹂躙拳', 'Effect Monster', 'Fiend', 'DARK', 10, 4000, 4000, '这张卡不能通常召唤。把自己场上3只怪兽解放的场合才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃，以自己场上1只「幻魔皇 拉比艾尔」为对象才能发动。这个回合，那只怪兽的攻击力变成2倍，可以向对方怪兽全部各作1次攻击。这个效果在对方回合也能发动。 ②：这张卡在墓地存在的场合，把自己场上1只怪兽解放才能发动。这张卡加入手卡。'),
(85309439, 'Ray & Temperature', '北风与太阳', '北風と太陽', 'Normal Monster', 'Fairy', 'LIGHT', 3, 1000, 1000, '交情深厚的北风和太阳，能发动飓风与热光线的攻击。'),
(82529174, 'Ray of Hope', '希望之光', '希望の光', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从自己墓地里选择2张光属性怪兽卡回到自己卡组。'),
(18372968, 'Razor Lizard', '剃刀蜥蜴', 'カミソーリトカゲ', 'Effect Monster', 'Reptile', 'EARTH', 3, 1500, 300, '只要自己场上有这张卡以外的爬虫类族怪兽表侧表示存在，这张卡攻击里侧守备表示怪兽的场合，不进行伤害计算以里侧守备表示的状态把那只怪兽破坏。'),
(77313225, 'Rciela, Sinister Soul of the White Forest', '白森的魔性 露西耶拉', '白き森の魔性ルシエラ', 'Synchro Tuner Monster', 'Spellcaster', 'LIGHT', 6, 2000, 1600, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合，从自己的手卡·场上把1张魔法·陷阱卡送去墓地才能发动。从卡组把1张「白森林」卡或1只魔法师族·光属性怪兽加入手卡。 ②：只要这张卡在怪兽区域存在，自己场上的幻想魔族·魔法师族的同调怪兽攻击力上升500，不会被对方的效果破坏。'),
(58695102, 'Re-Cover', '复活圣经', 'リ・バイブル', 'Tuner Monster', 'Psychic', 'EARTH', 1, 700, 300, '「再生圣经」的效果1回合只能使用1次。 ①：这张卡在墓地存在，自己的额外卡组的数量比对方少5张以上的场合，支付2000基本分才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(85704698, 'Re-dyce-cle', '再生骰子', 'リサイコロ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「疾行机人」调整为对象才能发动。那只怪兽效果无效特殊召唤，掷1次骰子。那只特殊召唤的怪兽直到回合结束时变成和出现的数目相同等级。 ②：把墓地的这张卡除外才能发动。用自己场上的包含「疾行机人」调整的怪兽为素材，把1只风属性同调怪兽同调召唤。'),
(74694807, 'Re-Fusion', '再融合', '再融合', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：支付800基本分，以自己墓地1只融合怪兽为对象才能把这张卡发动。那只怪兽特殊召唤，把这张卡装备。这张卡破坏时那只怪兽除外。'),
(20426907, 'Re-qliate', '机壳的再星', '機殻の再星', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：怪兽召唤·反转召唤时，那只怪兽是4星以下的场合把这个效果发动。那只怪兽的效果直到回合结束时无效。 ②：怪兽特殊召唤时，那怪兽是5星以上的场合把这个效果发动。那怪兽的效果直到回合结束时无效。那怪兽从场上离开的场合除外。 ③：场上没有「机壳的再星」以外的「机壳」卡存在的场合这张卡送去墓地。');